"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[6412],{5805(e,n,t){t.r(n),t.d(n,{assets:()=>c,contentTitle:()=>l,default:()=>h,frontMatter:()=>d,metadata:()=>s,toc:()=>u});const s=JSON.parse('{"id":"part2-backend-platform-security/enduser-vs-workload-identity","title":"Tenant Identity vs IAM vs Workload Identity (GCP) \u2014 The No-Confusion Guide","description":"This tutorial fixes the #1 enterprise confusion: tenant isolation (your SaaS data boundaries) is not the same thing as Cloud IAM (who can see/use GCP resources) and not the same thing as org group gating (who is allow...","source":"@site/docs/part2-backend-platform-security/10-enduser-vs-workload-identity.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/10-enduser-vs-workload-identity","permalink":"/tutorials/part2-backend-platform-security/10-enduser-vs-workload-identity","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":10,"frontMatter":{"title":"Tenant Identity vs IAM vs Workload Identity (GCP) \u2014 The No-Confusion Guide","slug":"/part2-backend-platform-security/10-enduser-vs-workload-identity","description":"This tutorial fixes the #1 enterprise confusion: tenant isolation (your SaaS data boundaries) is not the same thing as Cloud IAM (who can see/use GCP resources) and not the same thing as org group gating (who is allow...","sidebar_label":"12. End-user vs workload identity","pagination_label":"12. End-user vs workload identity","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"11. Passkeys, DPoP, mTLS, and token exchange","permalink":"/tutorials/part2-backend-platform-security/15-modern-auth-additions"},"next":{"title":"13. Tenant isolation, IAM, and groups","permalink":"/tutorials/part2-backend-platform-security/12-tenant-iam-ad-groups"}}');var i=t(4848),o=t(8453),a=t(8172);const r=JSON.parse('{"sourcePath":"part2-backend-platform-security/10-enduser-vs-workload-identity.html","route":"/part2-backend-platform-security/10-enduser-vs-workload-identity","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"Tenant Identity vs IAM vs Workload Identity (GCP)","title":"Tenant Identity vs IAM vs Workload Identity (GCP) \u2014 The No-Confusion Guide","description":"This tutorial fixes the #1 enterprise confusion: tenant isolation (your SaaS data boundaries) is not the same thing as Cloud IAM (who can see/use GCP resources) and not the same thing as org group gating (who is allow...","readingMinutes":6,"bodyClass":"","normalizeMath":false,"toc":[{"id":"three-lanes","label":"The 3-lane model (memorize this)"},{"id":"scenario1","label":"Scenario 1 \u2014 A normal end user uses your app (tenant isolation)"},{"id":"scenario2","label":"Scenario 2 \u2014 An internal employee sees buckets in the GCP Console (IAM)"},{"id":"scenario3","label":"Scenario 3 \u2014 Only users in an org group can use the app (allowlist gating)"},{"id":"together","label":"How all three show up in one request (the full picture)"},{"id":"mapping","label":"How Bearer token maps to user_id and tenant_id"},{"id":"workload","label":"How a service account is used to write to a bucket (workload identity)"},{"id":"code","label":"FastAPI examples (clean + simple)"},{"id":"mistakes","label":"Common mistakes (and the fix)"}],"html":"<div class=\\"container\\">\\n    \\n    <p class=\\"lead\\">\\n      This tutorial fixes the #1 enterprise confusion: <strong>tenant isolation</strong> (your SaaS data boundaries) is not the same thing as\\n      <strong>Cloud IAM</strong> (who can see/use GCP resources) and not the same thing as <strong>org group gating</strong> (who is allowed to use the app at all).\\n      We\u2019ll explain all three using your multi-tenant Doc Q&amp;A app as the running example.\\n    </p>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Reading path</strong>\\n      This chapter is the primary explanation of the three-lane identity\\n      model. <a href=\\"/tutorials/part2-backend-platform-security/12-tenant-iam-ad-groups\\">Chapter 13</a> applies the\\n      same model to AD/Workspace group gating and tenant bootstrap policy;\\n      <a href=\\"/tutorials/part2-backend-platform-security/11-gcp-workload-identity\\">Chapter 14</a> implements the\\n      workload-identity lane on GCP.\\n    </div>\\n\\n    <ul class=\\"toc\\">\\n      <li><a href=\\"#acronyms\\">Acronyms</a></li>\\n      <li><a href=\\"#three-lanes\\">The 3-lane model</a></li>\\n      <li><a href=\\"#scenario1\\">Scenario 1: Tenant isolation</a></li>\\n      <li><a href=\\"#scenario2\\">Scenario 2: GCP Console (IAM)</a></li>\\n      <li><a href=\\"#scenario3\\">Scenario 3: Org allowlist (groups)</a></li>\\n      <li><a href=\\"#together\\">One request: how they combine</a></li>\\n      <li><a href=\\"#mapping\\">Bearer token \u2192 user_id/tenant_id</a></li>\\n      <li><a href=\\"#workload\\">Service account \u2192 bucket/secrets</a></li>\\n      <li><a href=\\"#code\\">FastAPI examples</a></li>\\n      <li><a href=\\"#mistakes\\">Common mistakes</a></li>\\n    </ul>\\n\\n    <div class=\\"card\\" id=\\"acronyms\\">\\n      <h3 id=\\"acronyms-quick\\">Acronyms (quick)</h3>\\n      <ul>\\n        <li><strong>Tenant</strong>: a customer org (Company A vs Company B)</li>\\n        <li><strong>User</strong>: a human inside a tenant (Alice, Bob)</li>\\n        <li><strong>OIDC</strong>: login tokens from your IdP (Google Workspace)</li>\\n        <li><strong>JWT</strong>: token format often used for access tokens</li>\\n        <li><strong>IAM</strong>: GCP permissions to GCP resources (buckets, projects, secrets)</li>\\n        <li><strong>Service account</strong>: \u201cmachine identity\u201d your backend runs as</li>\\n        <li><strong>Workload Identity</strong>: how GKE/Cloud Run give pods/services service-account credentials without storing keys</li>\\n        <li><strong>Org allowlist / group gating</strong>: \u201conly members of Group X can use this app\u201d</li>\\n      </ul>\\n    </div>\\n\\n    <h2 id=\\"three-lanes\\">The 3-lane model (memorize this)</h2>\\n    <div class=\\"kv\\">\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Lane A \u2014 End-user identity</div>\\n        <div><strong>Who is calling?</strong> Comes in the HTTP request as <code>Authorization: Bearer ...</code>. Used to derive <code>user_id</code> and <code>tenant_id</code>.</div>\\n      </div>\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Lane B \u2014 App authorization</div>\\n        <div><strong>What can they see?</strong> Your code enforces tenant isolation (DB filters, search filters, RLS backstop).</div>\\n      </div>\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Lane C \u2014 Workload identity (IAM)</div>\\n        <div><strong>What can the service access?</strong> The backend\u2019s service account permissions to GCS, Secret Manager, Cloud SQL, logs.</div>\\n      </div>\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Org allowlist (gating)</div>\\n        <div><strong>Who is allowed in at all?</strong> Often based on Workspace/AD groups. Checked during bootstrap/login.</div>\\n      </div>\\n    </div>\\n\\n    <div class=\\"callout\\">\\n      <strong>Shortcut:</strong> Tenant isolation protects <em>customer data inside your app</em>. IAM protects <em>cloud resources</em>. Group gating protects <em>who can even use the app</em>.\\n    </div>\\n\\n    <h2 id=\\"scenario1\\">Scenario 1 \u2014 A normal end user uses your app (tenant isolation)</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"goal\\">Goal</h3>\\n      <p>Thousands of users can hit the same API, but each user can only access their tenant\u2019s documents.</p>\\n\\n      <h3 id=\\"what-makes-this-work\\">What makes this work</h3>\\n      <ol>\\n        <li>User logs in with Google Workspace \u2192 frontend receives an <strong>access token</strong>.</li>\\n        <li>Frontend calls your API with: <code>Authorization: Bearer &lt;token&gt;</code></li>\\n        <li>Backend validates token, extracts <code>user_id</code> and maps to <code>tenant_id</code>.</li>\\n        <li>Every DB/search call is scoped: <code>WHERE tenant_id = ...</code></li>\\n      </ol>\\n\\n      <div class=\\"callout\\">\\n        <strong>Key point:</strong> The user does <em>not</em> need GCP Console access. They are not an IAM principal for your cloud resources.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"scenario2\\">Scenario 2 \u2014 An internal employee sees buckets in the GCP Console (IAM)</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"goal-2\\">Goal</h3>\\n      <p>Some employees can see/modify buckets and projects in the GCP Console; others can\u2019t.</p>\\n\\n      <h3 id=\\"what-controls-visibility\\">What controls visibility</h3>\\n      <ol>\\n        <li>Employee signs into GCP Console with their corporate identity.</li>\\n        <li>GCP checks IAM bindings (direct user or group membership).</li>\\n        <li>Console shows resources they have permission to list/access.</li>\\n      </ol>\\n\\n      <div class=\\"warn\\">\\n        <strong>Common confusion:</strong> \u201cI can\u2019t see the bucket in console, so tenant isolation must be broken.\u201d  \\n        No \u2014 console visibility is <strong>IAM</strong>. Tenant isolation is <strong>your app\u2019s logic + DB policies</strong>.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"scenario3\\">Scenario 3 \u2014 Only users in an org group can use the app (allowlist gating)</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"goal-3\\">Goal</h3>\\n      <p>Only users in a particular org group (e.g., \u201cDocQA-Users\u201d) can use the app at all.</p>\\n\\n      <h3 id=\\"where-it-s-enforced\\">Where it\u2019s enforced</h3>\\n      <ol>\\n        <li>User logs in and obtains a token (OIDC).</li>\\n        <li>Frontend calls a bootstrap endpoint like <code>GET /me</code> or <code>POST /auth/bootstrap</code>.</li>\\n        <li>Backend verifies the token, then checks: \u201cIs this user in allowed group(s)?\u201d</li>\\n        <li>If not allowed \u2192 return <code>403</code>. If allowed \u2192 map to tenant and proceed.</li>\\n      </ol>\\n\\n      <div class=\\"callout\\">\\n        <strong>Group gating answers:</strong> \u201cCan you use the product?\u201d  \\n        <strong>Tenant isolation answers:</strong> \u201cWhich tenant\u2019s data can you access once inside?\u201d\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"together\\">How all three show up in one request (the full picture)</h2>\\n    <div class=\\"card\\">\\n      <p class=\\"muted\\">Think of it as three independent checks that happen in different places.</p>\\n      <ol>\\n        <li><strong>Lane A (OIDC token):</strong> Identify caller \u2192 <code>user_id</code>, claims, email.</li>\\n        <li><strong>Org gate:</strong> Is the user allowed group(s)? If no \u2192 <code>403</code>.</li>\\n        <li><strong>Lane B (tenant isolation):</strong> Determine <code>tenant_id</code> \u2192 scope DB/search to that tenant only.</li>\\n        <li><strong>Lane C (workload IAM):</strong> Backend service account reads secrets / reads &amp; writes to GCS / logs.</li>\\n      </ol>\\n\\n      <pre>POST /query HTTP/1.1\\nAuthorization: Bearer &lt;user_access_token&gt;\\nContent-Type: application/json\\n\\n{ \\"question\\": \\"What did Chandima mention on 1 Dec?\\" }</pre>\\n    </div>\\n\\n    <h2 id=\\"mapping\\">How Bearer token maps to user_id and tenant_id</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"why-the-token-string-itself-is-not-the-identity\\">Why the token string itself is not the identity</h3>\\n      <p>\\n        Access tokens rotate (expiry, refresh, re-login). The backend does not \u201crecognize\u201d a user by comparing token strings.\\n        Instead it validates the token and extracts a stable identity claim.\\n      </p>\\n\\n      <h3 id=\\"typical-mapping-logic\\">Typical mapping logic</h3>\\n      <ol>\\n        <li><strong>Verify token</strong> (signature + issuer + audience + expiry).</li>\\n        <li><strong>Extract stable user key</strong> (usually <code>sub</code>, combined with <code>iss</code>).</li>\\n        <li><strong>Derive tenant</strong> from:\\n          <ul>\\n            <li>a claim (e.g., <code>tid</code>/<code>tenant_id</code>) <em>or</em></li>\\n            <li>a DB lookup (issuer+sub \u2192 tenant_id) <em>or</em></li>\\n            <li>a policy mapping (email domain \u2192 tenant) for B2B setups.</li>\\n          </ul>\\n        </li>\\n      </ol>\\n\\n      <div class=\\"callout\\">\\n        <strong>Best practice:</strong> store users keyed by <code>(issuer, sub)</code> in your DB. That stays stable even when tokens change.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"workload\\">How a service account is used to write to a bucket (workload identity)</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"what-s-happening\\">What\u2019s happening</h3>\\n      <ul>\\n        <li>Your backend runs as a <strong>service account</strong> (machine identity).</li>\\n        <li>That service account is granted IAM permissions on a bucket (e.g., write objects).</li>\\n        <li>When your code calls the GCS SDK, it automatically obtains a short-lived access token for that service account.</li>\\n      </ul>\\n\\n      <div class=\\"callout\\">\\n        <strong>Key idea:</strong> The backend uses its own service identity to reach GCS/Secret Manager \u2014 not the end user\u2019s token.\\n        The end-user token only decides <em>which tenant path/object</em> the backend is allowed to touch.\\n      </div>\\n\\n      <div class=\\"warn\\">\\n        <strong>Important:</strong> If you let end users access buckets directly via IAM, you are mixing \u201ccloud control plane identity\u201d with \u201capp tenancy\u201d.\\n        Most SaaS designs avoid this \u2014 users access files through your API (or via signed URLs), while the backend holds storage permissions.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"code\\">FastAPI examples (clean + simple)</h2>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"1-end-user-identity-dependency-bearer-claims-user-id-tenant-id\\">1) End-user identity dependency (Bearer \u2192 claims \u2192 user_id/tenant_id)</h3>\\n      <p class=\\"muted\\">This is intentionally small: validate token, then map to tenant. In real code your JWT verification can use JWKS.</p>\\n\\n      <pre data-lang=\\"python\\"><code>from fastapi import Depends, FastAPI, HTTPException\\nfrom fastapi.security import HTTPAuthorizationCredentials, HTTPBearer\\nfrom pydantic import BaseModel\\n\\napp = FastAPI()\\nbearer = HTTPBearer(auto_error=True)\\n\\nclass Identity(BaseModel):\\n    user_id: str\\n    tenant_id: str\\n    email: str | None = None\\n\\ndef verify_jwt_and_get_claims(token: str) -&gt; dict:\\n    # In production: verify signature (JWKS), iss/aud/exp checks.\\n    # Here: pretend token is valid and return decoded claims.\\n    return {\\"sub\\": \\"user-123\\", \\"iss\\": \\"https://accounts.google.com\\", \\"email\\": \\"alice@acme.com\\"}\\n\\ndef map_claims_to_tenant(claims: dict) -&gt; str:\\n    # Example: domain-based tenant mapping (toy).\\n    email = claims.get(\\"email\\") or \\"\\"\\n    if \\"@\\" not in email:\\n        raise HTTPException(status_code=403, detail=\\"No tenant mapping\\")\\n    return email.split(\\"@\\", 1)[1]  # \\"acme.com\\"\\n\\ndef require_allowed_group(claims: dict) -&gt; None:\\n    # Example gate. In real life you would check group membership via claims or directory lookup.\\n    # If user is not in allowed group(s), block the app.\\n    allowed = True\\n    if not allowed:\\n        raise HTTPException(status_code=403, detail=\\"Not allowed to use the app\\")\\n\\ndef get_identity(creds: HTTPAuthorizationCredentials = Depends(bearer)) -&gt; Identity:\\n    claims = verify_jwt_and_get_claims(creds.credentials)\\n    require_allowed_group(claims)\\n\\n    user_id = claims[\\"sub\\"]\\n    tenant_id = map_claims_to_tenant(claims)\\n    return Identity(user_id=user_id, tenant_id=tenant_id, email=claims.get(\\"email\\"))\\n\\n@app.get(\\"/me\\")\\ndef me(ident: Identity = Depends(get_identity)):\\n    return ident</code></pre>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"2-workload-identity-in-code-service-account-secret-manager-gcs\\">2) Workload identity in code (service account \u2192 Secret Manager / GCS)</h3>\\n      <p class=\\"muted\\">No keys in code. The SDK picks up the pod/service\u2019s identity automatically.</p>\\n\\n      <pre data-lang=\\"python\\"><code># pip install google-cloud-secret-manager google-cloud-storage\\n\\nfrom google.cloud import secretmanager, storage\\n\\ndef read_secret_value(secret_resource_name: str) -&gt; str:\\n    # Uses workload identity (service account) behind the scenes.\\n    client = secretmanager.SecretManagerServiceClient()\\n    resp = client.access_secret_version(request={\\"name\\": secret_resource_name})\\n    return resp.payload.data.decode(\\"utf-8\\")\\n\\ndef write_tenant_object(bucket: str, tenant_id: str, object_name: str, data: bytes) -&gt; None:\\n    # Uses workload identity; IAM decides if this service account can write.\\n    gcs = storage.Client()\\n    b = gcs.bucket(bucket)\\n\\n    # App tenancy decides *where* we write (tenant prefix).\\n    blob = b.blob(f\\"{tenant_id}/{object_name}\\")\\n    blob.upload_from_string(data)</code></pre>\\n\\n      <div class=\\"callout\\">\\n        <strong>Separation of duties:</strong> IAM answers \u201ccan the service write to this bucket at all?\u201d\\n        Tenant isolation answers \u201cwhich tenant prefix/object is allowed for this request?\u201d\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"mistakes\\">Common mistakes (and the fix)</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"mistake-1-tenant-iam\\">\u274c Mistake 1: \u201cTenant = IAM\u201d</h3>\\n      <p><strong>Wrong:</strong> \u201cIf IAM is correct, tenants are isolated.\u201d</p>\\n      <p><strong>Right:</strong> IAM is cloud infra permissions. Tenant isolation is your app filtering + DB policy (RLS as backstop).</p>\\n\\n      <h3 id=\\"mistake-2-passing-user-tokens-to-cloud-apis\\">\u274c Mistake 2: Passing user tokens to cloud APIs</h3>\\n      <p><strong>Wrong:</strong> backend calls Secret Manager with the user\u2019s Bearer token.</p>\\n      <p><strong>Right:</strong> backend calls cloud APIs using its service account. User token only controls tenant scoping and app permissions.</p>\\n\\n      <h3 id=\\"mistake-3-losing-tenant-context-in-async-background-work\\">\u274c Mistake 3: Losing tenant context in async/background work</h3>\\n      <p><strong>Wrong:</strong> enqueue a job without storing <code>tenant_id</code>.</p>\\n      <p><strong>Right:</strong> persist <code>tenant_id</code> with the job and enforce tenant checks when the job runs.</p>\\n\\n      <div class=\\"warn\\">\\n        <strong>Bank-grade habit:</strong> add an audit record for \u201cwho requested what\u201d (end-user identity) and \u201cwhich workload executed it\u201d (service identity).\\n      </div>\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Identity rule to carry forward</strong>\\n      Preserve both actors in every sensitive audit event: the end user who\\n      requested the action and the workload identity that executed it.\\n      Authorization uses the user\'s application permissions; cloud API access\\n      uses the workload\'s IAM permissions.\\n    </div>\\n  </div>"}'),d={title:"Tenant Identity vs IAM vs Workload Identity (GCP) \u2014 The No-Confusion Guide",slug:"/part2-backend-platform-security/10-enduser-vs-workload-identity",description:"This tutorial fixes the #1 enterprise confusion: tenant isolation (your SaaS data boundaries) is not the same thing as Cloud IAM (who can see/use GCP resources) and not the same thing as org group gating (who is allow...",sidebar_label:"12. End-user vs workload identity",pagination_label:"12. End-user vs workload identity",hide_title:!0,hide_table_of_contents:!0},l=void 0,c={},u=[];function p(e){return(0,i.jsx)(a.A,{content:r})}function h(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(p,{...e})}):p()}}}]);